SELECT t.id, t.warehouse_id, t.weekdays, t.slot_start, t.slot_end, t.capacity, t.task_type, t.enabled, t.remark FROM yms_slot_template t WHERE t.deleted = 0
AND t.warehouse_id = #{bo.warehouseId}
AND (t.task_type = #{bo.taskType} OR t.task_type = 'ALL')
AND t.enabled = #{bo.enabled}
ORDER BY t.slot_start ASC

SELECT t.id, t.warehouse_id, t.weekdays, t.slot_start, t.slot_end, t.capacity, t.task_type, t.enabled, t.remark FROM yms_slot_template t WHERE t.deleted = 0 AND t.enabled = 1 AND t.warehouse_id = #{warehouseId}
AND (t.task_type = #{taskType} OR t.task_type = 'ALL')
ORDER BY t.slot_start ASC
